use core.files as files
use core.process as process
use core.text as text

struct Entry {
    key: String
    value: String
    active: Bool
}
fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    content :: files.read(path) ?? panic("read failed")
    entries := [Entry]{}

    loop raw in content.lines() {
        line :: ~(raw.trim())
        if line.is_empty() -> next
        parts :: text.splitn(line, "|", 3)
        kind :: parts.get(0) ?? panic("malformed record")
        key :: parts.get(1) ?? panic("malformed record")
        value :: parts.get(2) ?? panic("malformed record")

        if kind == "put" {
            found := false
            i := 0
            loop i < entries.len() {
                entry :: entries.get(i) ?? panic("missing entry")
                if entry.key == key && entry.active {
                    entries[i].value = ~value
                    found = true
                }
                i += 1
            }
            if !found -> entries.push(Entry{key: key, value: value, active: true})
        } else if kind == "delete" {
            if !value.is_empty() -> panic("delete value must be empty")
            i := 0
            loop i < entries.len() {
                entry :: entries.get(i) ?? panic("missing entry")
                if entry.key == key && entry.active -> entries[i].active = false
                i += 1
            }
        } else {
            panic("unknown record {kind}")
        }
    }

    loop entry in entries {
        if entry.active -> print("{entry.key}={entry.value}")
    }
}
